class FindTests(unittest.TestCase):
    def test_real_forms_match(self):
        for text in MUST_MATCH:
            with self.subTest(text=text):
                self.assertTrue(attribution_check.find(text))

    def test_prose_passes(self):
        for text in MUST_PASS:
            with self.subTest(text=text):
                self.assertEqual([], attribution_check.find(text))

    def test_git_comment_lines_are_ignored(self):
        self.assertEqual("Fix", attribution_check.strip_git_comments("Fix\n# Generated by Claude Code\n"))


class FakeApi:
    def __init__(self, title="Clean", body="Closes #1", commits=("Fix",), comments=(), reviews=(), review_comments=()):
        self.calls, self.title, self.body = [], title, body
        self.commits, self.comments, self.reviews, self.review_comments = commits, comments, reviews, review_comments

    def __call__(self, method, path, body=None):
        self.calls.append((method, path, body))
        if method == "POST":
            return None, None
        if path.endswith("/pulls/7"):
            return {"title": self.title, "body": self.body, "head": {"sha": "abcdef1234"}}, None
        base = path.split("?")[0]
        if base.endswith("/commits"):
            return [{"sha": f"{i:040d}", "commit": {"message": m}} for i, m in enumerate(self.commits)], None
        if base.endswith("/issues/7/comments"):
            return [{"id": 10 + i, "body": b} for i, b in enumerate(self.comments)], None
        if base.endswith("/pulls/7/reviews"):
            return [{"id": 20 + i, "body": b} for i, b in enumerate(self.reviews)], None
        if base.endswith("/pulls/7/comments"):
            return [{"id": 30 + i, "body": b} for i, b in enumerate(self.review_comments)], None
        raise AssertionError(path)

    def status(self):
        posts = [c for c in self.calls if c[0] == "POST"]
        return posts[-1][1], posts[-1][2]


class ApiErrorTests(unittest.TestCase):
    def run_main(self, error):
        import contextlib
        import io
        import os
        from unittest import mock
        stderr = io.StringIO()
        with mock.patch.dict(os.environ, {"GITHUB_TOKEN": "secret-token"}), \
                mock.patch.object(attribution_check, "github_request", side_effect=error), \
                contextlib.redirect_stderr(stderr):
            code = attribution_check.main(["pr", "7", "--repo", "o/r"])
        return code, stderr.getvalue()

    def test_http_error_exits_2_with_one_line(self):
        import urllib.error
        error = urllib.error.HTTPError("https://api.github.com/x", 403, "Forbidden", {}, None)
        code, out = self.run_main(error)
        self.assertEqual(2, code)
        self.assertEqual("ERROR: GitHub API 403 Forbidden for GET /repos/o/r/pulls/7\n", out)
        self.assertNotIn("secret-token", out)

    def test_url_error_exits_2(self):
        import urllib.error
        code, out = self.run_main(urllib.error.URLError("down"))
        self.assertEqual(2, code)
        self.assertEqual(1, len(out.strip().splitlines()))
        self.assertNotIn("Traceback", out)


class PullRequestTests(unittest.TestCase):
    def run_scan(self, **kwargs):
        api = FakeApi(**kwargs)
        code = attribution_check.run_pull_request(api, "o/r", 7, set_status=True)
        self.assertEqual(0, code)
        return api.status()

    def test_clean_pull_request_is_green(self):
        path, payload = self.run_scan()
        self.assertEqual("/repos/o/r/statuses/abcdef1234", path)
        self.assertEqual("success", payload["state"])
        self.assertEqual(attribution_check.STATUS_CONTEXT, payload["context"])

    def test_each_location_turns_red(self):
        cases = {
            "title": {"title": "Generated by Claude Code"},
            "body": {"body": "x\nCo-Authored-By: Claude <noreply@anthropic.com>"},
            "commit": {"commits": ("Fix", "Generated with Claude Code")},
            "comment": {"comments": ("fine", "https://claude.ai/code/session_abc")},
            "review": {"reviews": ("Reviewed by Claude Code",)},
            "review comment": {"review_comments": ("Generated by [Claude Code](https://x)",)},
        }
        for location, kwargs in cases.items():
            with self.subTest(location=location):
                _, payload = self.run_scan(**kwargs)
                self.assertEqual("failure", payload["state"])
                self.assertIn(location, payload["description"].lower())

    def test_description_stays_within_the_status_limit(self):
        _, payload = self.run_scan(commits=tuple("Generated by Claude Code" for _ in range(40)))
        self.assertLessEqual(len(payload["description"]), 140)

    def test_without_set_status_a_match_exits_1_and_writes_nothing(self):
        api = FakeApi(body="Generated by Claude Code")
        self.assertEqual(1, attribution_check.run_pull_request(api, "o/r", 7, set_status=False))
        self.assertFalse([c for c in api.calls if c[0] == "POST"])


if __name__ == "__main__":
    unittest.main()


class HookTests(unittest.TestCase):
    """hooks/commit-msg in a scratch repository: from a clone (core.hooksPath) and as an installed copy."""

    def setUp(self):
        import shutil, subprocess, tempfile
        self.subprocess = subprocess
        self.temp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.temp, ignore_errors=True)
        self.git("init", "-q")
        self.copy = Path(self.temp) / "installed"
        self.copy.mkdir()
        for source in (ROOT / "hooks" / "commit-msg", ROOT / "scripts" / "attribution_check.py"):
            shutil.copy(source, self.copy / source.name)

    def git(self, *args):
        base = ["git", "-c", "user.name=t", "-c", "user.email=t@example.invalid", "-c", "commit.gpgsign=false"]
        return self.subprocess.run(base + list(args), cwd=self.temp, capture_output=True, text=True)

    def commit(self, hooks, message):
        return self.git("-c", f"core.hooksPath={hooks}", "commit", "--allow-empty", "-m", message)

    def test_hook_refuses_and_accepts(self):
        for hooks in (ROOT / "hooks", self.copy):
            with self.subTest(hooks=hooks.name):
                refused = self.commit(hooks, "Fix\n\nCo-Authored-By: Claude <noreply@anthropic.com>")
                self.assertNotEqual(refused.returncode, 0)
                self.assertIn("attribution", refused.stderr)
                self.assertEqual(self.commit(hooks, "Fix the parser").returncode, 0, refused.stderr)
